function t(key) {
  return copy[state.lang][key] || key;
}

function dateKey(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return year + '-' + month + '-' + day;
}

function selectedDateKey() {
  const date = new Date(state.shownYear, state.shownMonth, state.selectedDay);
  return dateKey(date);
}

function dateFromKey(key) {
  const parts = key.split('-').map(Number);
  return new Date(parts[0], parts[1] - 1, parts[2]);
}

function addDays(date, amount) {
  const result = new Date(date);
  result.setDate(result.getDate() + amount);
  return result;
}

function daysBetween(first, second) {
  return Math.round((dateFromKey(second) - dateFromKey(first)) / 86400000);
}

function keysBetween(start, end) {
  const keys = [];
  for (let current = new Date(start); current <= end; current = addDays(current, 1)) {
    keys.push(dateKey(current));
  }
  return keys;
}

function buildLocalCalendarForecast(year, month) {
  const monthStart = new Date(year, month, 1);
  const monthEnd = new Date(year, month + 1, 0);
  const periods = state.periods.map(function (period) {
    const start = dateFromKey(period.start_date);
    const end = dateFromKey(period.end_date || period.start_date);
    return { start: start, end: end < start ? start : end, complete: Boolean(period.end_date) };
  }).sort(function (first, second) {
    return first.start - second.start;
  });
  const starts = Array.from(new Set(periods.map(function (period) {
    return dateKey(period.start);
  }))).map(dateFromKey);
  const gaps = [];
  for (let index = 1; index < starts.length; index += 1) {
    const gap = Math.round((starts[index] - starts[index - 1]) / 86400000);
    if (gap >= 21 && gap <= 45) gaps.push(gap);
  }
  const lengths = periods.filter(function (period) {
    return period.complete;
  }).map(function (period) {
    return Math.round((period.end - period.start) / 86400000) + 1;
  }).filter(function (length) {
    return length >= 1 && length <= 10;
  });
  const average = function (values, fallback) {
    return values.length ? Math.round(values.reduce(function (sum, value) {
      return sum + value;
    }, 0) / values.length) : fallback;
  };
  const cycleLength = average(gaps, 28);
  const periodLength = average(lengths, 5);
  const recorded = new Set();
  periods.forEach(function (period) {
    keysBetween(period.start, period.end).forEach(function (key) {
      const day = dateFromKey(key);
      if (day >= monthStart && day <= monthEnd) recorded.add(key);
    });
  });
  const result = {
    year: year,
    month: month + 1,
    has_data: Boolean(starts.length),
    cycle_length: cycleLength,
    period_length: periodLength,
    current_cycle_day: null,
    current_phase: 'unknown',
    next_period_start: null,
    next_fertile_start: null,
    next_fertile_end: null,
    recorded_period_dates: Array.from(recorded).sort(),
    predicted_period_dates: [],
    fertile_dates: [],
    ovulation_dates: []
  };
  if (!starts.length) return result;

  const anchor = starts[starts.length - 1];
  let nextPeriod = new Date(anchor);
  while (nextPeriod <= today) nextPeriod = addDays(nextPeriod, cycleLength);
  const elapsed = Math.floor((today - anchor) / 86400000);
  if (elapsed >= 0) {
    const currentDay = elapsed % cycleLength + 1;
    const currentStart = addDays(today, -(currentDay - 1));
    const ovulation = addDays(currentStart, Math.max(0, cycleLength - 14));
    const fertileStart = addDays(ovulation, -5);
    const fertileEnd = addDays(ovulation, 1);
    result.current_cycle_day = currentDay;
    if (currentDay <= periodLength) result.current_phase = 'period';
    else if (today >= fertileStart && today <= fertileEnd) result.current_phase = dateKey(today) === dateKey(ovulation) ? 'ovulation' : 'fertile';
    else result.current_phase = today < fertileStart ? 'follicular' : 'luteal';
  }

  let fertileCycleStart = new Date(nextPeriod);
  let nextOvulation = addDays(fertileCycleStart, -14);
  let nextFertileStart = addDays(nextOvulation, -5);
  let nextFertileEnd = addDays(nextOvulation, 1);
  if (nextFertileEnd < today) {
    fertileCycleStart = addDays(fertileCycleStart, cycleLength);
    nextOvulation = addDays(fertileCycleStart, -14);
    nextFertileStart = addDays(nextOvulation, -5);
    nextFertileEnd = addDays(nextOvulation, 1);
  }
  result.next_period_start = dateKey(nextPeriod);
  result.next_fertile_start = dateKey(nextFertileStart);
  result.next_fertile_end = dateKey(nextFertileEnd);

  const predicted = new Set();
  const fertile = new Set();
  const ovulations = new Set();
  let cycleStart = new Date(anchor);
  const searchEnd = addDays(monthEnd, cycleLength);
  while (cycleStart <= searchEnd) {
    if (cycleStart > anchor) {
      keysBetween(cycleStart, addDays(cycleStart, periodLength - 1)).forEach(function (key) {
        const day = dateFromKey(key);
        if (day >= monthStart && day <= monthEnd && !recorded.has(key)) predicted.add(key);
      });
    }
    const ovulation = addDays(cycleStart, Math.max(0, cycleLength - 14));
    keysBetween(addDays(ovulation, -5), addDays(ovulation, 1)).forEach(function (key) {
      const day = dateFromKey(key);
      if (day >= monthStart && day <= monthEnd) fertile.add(key);
    });
    if (ovulation >= monthStart && ovulation <= monthEnd) ovulations.add(dateKey(ovulation));
    cycleStart = addDays(cycleStart, cycleLength);
  }
  result.predicted_period_dates = Array.from(predicted).sort();
  result.fertile_dates = Array.from(fertile).sort();
  result.ovulation_dates = Array.from(ovulations).sort();
  return result;
}

function formatDate(key) {
  const locale = state.lang === 'kk' ? 'kk-KZ' : 'ru-RU';
  return new Intl.DateTimeFormat(locale, { day: 'numeric', month: 'long' }).format(dateFromKey(key));
}

function showToast(message) {
  const toast = document.querySelector('#toast');
  toast.textContent = message;
  toast.classList.add('show');
  setTimeout(function () {
    toast.classList.remove('show');
  }, 2100);
}

function setView(view) {
  state.view = view;
  document.querySelectorAll('.view').forEach(function (panel) {
    panel.classList.toggle('active', panel.dataset.viewPanel === view);
  });
  document.querySelectorAll('[data-view]').forEach(function (button) {
    button.classList.toggle('active', button.dataset.view === view);
  });

  const name = localStorage.getItem('sana-user-name') || 'Амина';
  const titles = {
    home: state.lang === 'kk' ? 'Сәлем, ' + name : 'Здравствуйте, ' + name,
    calendar: t('navCalendar'),
    insights: t('navInsights'),
    chat: t('navChat'),
    profile: t('navProfile'),
    log: t('dailyLog')
  };
  document.querySelector('#pageTitle').textContent = titles[view];
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

function applyProfileName(name) {
  const safeName = name || 'Амина';
  const initial = safeName.trim().charAt(0).toUpperCase() || 'А';
  document.querySelector('#profileName').textContent = safeName;
  document.querySelector('#profileAvatar').textContent = initial;
  document.querySelector('.avatar').textContent = initial;
  document.querySelector('#sideProfileName').textContent = safeName;
  document.querySelector('#sideProfileAvatar').textContent = initial;
}

function applyLanguage(lang) {
  state.lang = lang;
  localStorage.setItem('sana-lang', lang);
  document.documentElement.lang = lang;

  document.querySelectorAll('[data-i18n]').forEach(function (element) {
    element.textContent = t(element.dataset.i18n);
  });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(function (element) {
    element.placeholder = t(element.dataset.i18nPlaceholder);
  });
  document.querySelectorAll('.lang').forEach(function (button) {
    button.classList.toggle('active', button.dataset.lang === lang);
  });

  document.querySelector('#languageValue').textContent = lang === 'kk' ? 'Қазақша' : 'Русский';
  const locale = lang === 'kk' ? 'kk-KZ' : 'ru-RU';
  const todayText = new Intl.DateTimeFormat(locale, { day: 'numeric', month: 'long' }).format(today);
  document.querySelector('#todayLabel').textContent = (lang === 'kk' ? 'Бүгін • ' : 'Сегодня • ') + todayText;
  updateNotificationsText();
  renderForecastSummary();
  updateSelectedDate();
  updateLoggerDate();
  renderCalendar();
  renderCharts();
  renderChat();
  setView(state.view);
}

function updateSelectedDate() {
  const key = selectedDateKey();
  document.querySelector('#selectedDate').textContent = formatDate(key);
  const log = state.logs.get(key);
  document.querySelector('#calendarMood').textContent = log ? t(log.mood) : t('notMarked');
  document.querySelector('#calendarEnergy').textContent = log ? t(log.energy) : t('notMarked');
  const note = log && log.notes ? log.notes.trim() : '';
  document.querySelector('#calendarNoteText').textContent = note || t('noNotes');
  document.querySelector('#calendarNotePanel').classList.toggle('empty', !note);
  const phase = phaseForDate(key);
  document.querySelector('#calendarPhaseTitle').textContent = t(phase.title);
  document.querySelector('#calendarPhaseDetail').textContent = t(phase.detail);
  document.querySelector('#calendarNextPeriod').textContent = state.calendar && state.calendar.next_period_start
    ? formatDate(state.calendar.next_period_start)
    : '—';
  const existingPeriod = getPeriodForDate(key);
  document.querySelector('#markSelectedPeriodText').textContent = t(existingPeriod ? 'removePeriod' : 'markPeriodStart');
}

function phaseForDate(key) {
  if (isPeriodDate(key)) return { title: 'phasePeriod', detail: 'recordedDay' };
  if (isPredictedPeriodDate(key)) return { title: 'phasePeriod', detail: 'predictedDay' };
  if (state.calendar && state.calendar.ovulation_dates.includes(key)) return { title: 'phaseOvulation', detail: 'predictedDay' };
  if (isFertileDate(key)) return { title: 'phaseFertile', detail: 'predictedDay' };
  return { title: 'ordinaryDay', detail: state.calendar && state.calendar.has_data ? 'noPredictionForDay' : 'notEnoughData' };
}

function phaseTranslation(phase) {
  const phases = {
    period: 'phasePeriod',
    fertile: 'phaseFertile',
    ovulation: 'phaseOvulation',
    follicular: 'phaseFollicular',
    luteal: 'phaseLuteal'
  };
  return t(phases[phase] || 'notEnoughData');
}

function renderForecastSummary() {
  const calendar = state.calendar;
  const hasData = calendar && calendar.has_data;
  document.querySelector('#cyclePhase').textContent = hasData ? phaseTranslation(calendar.current_phase) : t('notEnoughData');
  document.querySelector('#cycleDayValue').textContent = hasData && calendar.current_cycle_day ? calendar.current_cycle_day : '—';
  document.querySelector('#cycleLengthValue').textContent = hasData ? calendar.cycle_length : '—';
  document.querySelector('#overviewCycleLength').textContent = hasData ? calendar.cycle_length : '—';
  document.querySelector('#overviewPeriodLength').textContent = hasData ? calendar.period_length : '—';
  document.querySelector('#cycleDataStatus').textContent = hasData ? t('cycleCalculated') : t('markFirstPeriod');
  document.querySelector('#fertileRange').textContent = hasData && calendar.next_fertile_start
    ? formatDate(calendar.next_fertile_start) + ' — ' + formatDate(calendar.next_fertile_end)
    : t('notEnoughData');
  if (hasData && calendar.next_period_start) {
    const days = Math.max(0, daysBetween(dateKey(today), calendar.next_period_start));
    document.querySelector('#nextPeriodText').textContent = t('daysUntilPeriod').replace('{days}', days);
  } else {
    document.querySelector('#nextPeriodText').textContent = t('markFirstPeriod');
  }
  const progress = hasData && calendar.current_cycle_day
    ? Math.min(1, calendar.current_cycle_day / calendar.cycle_length)
    : 0;
  document.querySelector('.ring-progress').style.strokeDashoffset = String(616 * (1 - progress));
}

function renderCalendar() {
  document.querySelector('#monthTitle').textContent = months[state.lang][state.shownMonth] + ' ' + state.shownYear;
  const grid = document.querySelector('#calendarGrid');
  grid.innerHTML = '';

  const firstWeekday = (new Date(state.shownYear, state.shownMonth, 1).getDay() + 6) % 7;
  const days = new Date(state.shownYear, state.shownMonth + 1, 0).getDate();
  const previousDays = new Date(state.shownYear, state.shownMonth, 0).getDate();

  for (let index = firstWeekday - 1; index >= 0; index -= 1) {
    addDay(previousDays - index, true);
  }
  for (let day = 1; day <= days; day += 1) {
    addDay(day, false);
  }
  while (grid.children.length % 7) {
    addDay(grid.children.length - days - firstWeekday + 1, true);
  }

  function addDay(day, muted) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'calendar-day';
    button.textContent = day;

    if (muted) {
      button.classList.add('muted');
    } else {
      const key = dateKey(new Date(state.shownYear, state.shownMonth, day));
      const log = state.logs.get(key);
      if (log) button.classList.add('logged');
      if (isPeriodDate(key)) button.classList.add('period');
      else if (isPredictedPeriodDate(key)) button.classList.add('predicted-period');
      if (isFertileDate(key)) button.classList.add('fertile');
      if (key === dateKey(today)) button.classList.add('today');
      if (day === state.selectedDay) button.classList.add('selected');
      button.addEventListener('click', function () {
        state.selectedDay = day;
        updateSelectedDate();
        renderCalendar();
      });
    }
    grid.appendChild(button);
  }

  const week = state.lang === 'kk'
    ? ['Дс', 'Сс', 'Ср', 'Бс', 'Жм', 'Сб', 'Жс']
    : ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];
  document.querySelectorAll('.weekdays span').forEach(function (element, index) {
    element.textContent = week[index];
  });
  renderHomeCalendar(week);
}

function renderHomeCalendar(week) {
  const grid = document.querySelector('#homeCalendarGrid');
  if (!grid) return;

  document.querySelector('#homeMonthTitle').textContent = months[state.lang][state.shownMonth] + ' ' + state.shownYear;
  document.querySelectorAll('.home-weekdays span').forEach(function (element, index) {
    element.textContent = week[index];
  });
  grid.innerHTML = '';

  const firstWeekday = (new Date(state.shownYear, state.shownMonth, 1).getDay() + 6) % 7;
  const days = new Date(state.shownYear, state.shownMonth + 1, 0).getDate();
  const previousDays = new Date(state.shownYear, state.shownMonth, 0).getDate();

  for (let index = firstWeekday - 1; index >= 0; index -= 1) {
    addHomeDay(previousDays - index, true);
  }
  for (let day = 1; day <= days; day += 1) {
    addHomeDay(day, false);
  }
  while (grid.children.length % 7) {
    addHomeDay(grid.children.length - days - firstWeekday + 1, true);
  }

  function addHomeDay(day, muted) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'home-calendar-day';
    button.textContent = day;
    if (muted) {
      button.classList.add('muted');
      button.disabled = true;
    } else {
      const key = dateKey(new Date(state.shownYear, state.shownMonth, day));
      if (state.logs.has(key)) button.classList.add('logged');
      if (isPeriodDate(key)) button.classList.add('period');
      else if (isPredictedPeriodDate(key)) button.classList.add('predicted-period');
      if (isFertileDate(key)) button.classList.add('fertile');
      if (key === dateKey(today)) button.classList.add('today');
      button.addEventListener('click', function () {
        state.selectedDay = day;
        updateSelectedDate();
        renderCalendar();
        setView('calendar');
      });
    }
    grid.appendChild(button);
  }
}

function isPeriodDate(key) {
  const target = dateFromKey(key).getTime();
  return state.periods.some(function (period) {
    const start = dateFromKey(period.start_date).getTime();
    const end = period.end_date ? dateFromKey(period.end_date).getTime() : start;
    return target >= start && target <= end;
  });
}

function getPeriodForDate(key) {
  const target = dateFromKey(key).getTime();
  return state.periods.find(function (period) {
    const start = dateFromKey(period.start_date).getTime();
    const end = dateFromKey(period.end_date || period.start_date).getTime();
    return target >= start && target <= end;
  });
}

function isPredictedPeriodDate(key) {
  return Boolean(state.calendar && state.calendar.predicted_period_dates.includes(key));
}

function isFertileDate(key) {
  return Boolean(state.calendar && state.calendar.fertile_dates.includes(key));
}

function updateLoggerDate() {
  document.querySelector('#loggerDate').textContent = formatDate(state.logDate);
}

function fillLogForm(key) {
  const log = state.logs.get(key);
  state.logDate = key;
  state.mood = log ? log.mood : 'calm';
  state.energy = log ? log.energy : 'medium';
  state.symptoms = log && log.symptoms.length ? log.symptoms.slice() : ['none'];
  document.querySelector('#notes').value = log ? log.notes : '';
  updateLoggerDate();
  syncLogChoices();
}

function syncLogChoices() {
  document.querySelectorAll('#moodChoices button').forEach(function (button) {
    button.classList.toggle('selected', button.dataset.value === state.mood);
  });
  document.querySelectorAll('#energyChoices button').forEach(function (button) {
    button.classList.toggle('selected', button.dataset.value === state.energy);
  });
  document.querySelectorAll('#symptomChoices button').forEach(function (button) {
    button.classList.toggle('selected', state.symptoms.includes(button.dataset.value));
  });
  document.querySelectorAll('.mood').forEach(function (button) {
    button.classList.toggle('selected', button.dataset.mood === state.mood);
  });
}

function openLog() {
  const key = state.view === 'calendar' ? selectedDateKey() : dateKey(today);
  fillLogForm(key);
  setView('log');
}

function readLocalLogs() {
  try {
    const logs = JSON.parse(localStorage.getItem('sana-logs') || '[]');
    return Array.isArray(logs) ? logs : [];
  } catch (error) {
    return [];
  }
}

function cacheLogs() {
  localStorage.setItem('sana-logs', JSON.stringify(Array.from(state.logs.values())));
}

function readLocalPeriods() {
  try {
    const periods = JSON.parse(localStorage.getItem('sana-periods') || '[]');
    return Array.isArray(periods) ? periods : [];
  } catch (error) {
    return [];
  }
}

function cachePeriods() {
  localStorage.setItem('sana-periods', JSON.stringify(state.periods));
}

function setLogs(logs) {
  state.logs.clear();
  logs.forEach(function (log) {
    if (!state.logs.has(log.entry_date)) state.logs.set(log.entry_date, log);
  });
}

async function apiRequest(path, options) {
  const response = await fetch(path, options);
  const data = await response.json().catch(function () {
    return {};
  });
  if (!response.ok) {
    const error = new Error(data.detail || 'API error: ' + response.status);
    error.status = response.status;
    throw error;
  }
  return data;
}

async function loadTrackerData() {
  try {
    const responses = await Promise.all([
      apiRequest('/api/logs?limit=100'),
      apiRequest('/api/periods')
    ]);
    setLogs(responses[0]);
    state.periods = responses[1];
    cacheLogs();
    cachePeriods();
  } catch (error) {
    setLogs(readLocalLogs());
    state.periods = readLocalPeriods();
  }
  await loadCalendarForecast();
  renderForecastSummary();
  updateSelectedDate();
  renderCalendar();
  renderCharts();
}

async function loadCalendarForecast() {
  try {
    state.calendar = await apiRequest(
      '/api/calendar?year=' + state.shownYear + '&month=' + (state.shownMonth + 1)
    );
  } catch (error) {
    state.calendar = buildLocalCalendarForecast(state.shownYear, state.shownMonth);
  }
}

async function saveLog() {
  const payload = {
    entry_date: state.logDate,
    mood: state.mood,
    energy: state.energy,
    symptoms: state.symptoms,
    notes: document.querySelector('#notes').value.trim()
  };

  let saved = payload;
  try {
    saved = await apiRequest('/api/logs', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
  } catch (error) {
    saved = Object.assign({ id: Date.now(), created_at: new Date().toISOString() }, payload);
  }

  state.logs.set(saved.entry_date, saved);
  const savedDate = dateFromKey(saved.entry_date);
  state.shownYear = savedDate.getFullYear();
  state.shownMonth = savedDate.getMonth();
  state.selectedDay = savedDate.getDate();
  state.logDate = saved.entry_date;
  cacheLogs();
  updateSelectedDate();
  renderCalendar();
  renderCharts();
  showToast(t('saved'));
  setTimeout(function () {
    setView('calendar');
  }, 400);
}

async function markPeriod(key) {
  const existing = getPeriodForDate(key);
  if (existing) {
    try {
      await apiRequest('/api/periods/' + existing.id, { method: 'DELETE' });
    } catch (error) {
      // GitHub Pages uses the local fallback below.
    }
    state.periods = state.periods.filter(function (period) {
      return period.id !== existing.id;
    });
    showToast(t('periodRemoved'));
  } else {
    const payload = { start_date: key, end_date: null };
    let saved = payload;
    try {
      saved = await apiRequest('/api/periods', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
    } catch (error) {
      saved = Object.assign({ id: Date.now() }, payload);
    }
    state.periods.unshift(saved);
    showToast(t('periodSaved'));
  }
  cachePeriods();
  await loadCalendarForecast();
  renderForecastSummary();
  updateSelectedDate();
  renderCalendar();
}

function renderCharts() {
  document.querySelector('#savedEntriesCount').textContent = state.logs.size;
  renderWeeklyChart();
  renderEnergyChart();
}

function renderWeeklyChart() {
  const bars = Array.from(document.querySelectorAll('.mini-chart > div'));
  const dates = [];
  for (let offset = 6; offset >= 0; offset -= 1) {
    const date = new Date(today);
    date.setDate(today.getDate() - offset);
    dates.push(date);
  }

  const locale = state.lang === 'kk' ? 'kk-KZ' : 'ru-RU';
  const scores = [];
  bars.forEach(function (bar, index) {
    const date = dates[index];
    const log = state.logs.get(dateKey(date));
    const score = log ? energyScore[log.energy] : 0;
    scores.push(score);
    bar.style.setProperty('--h', score ? (18 + score * 24) + '%' : '8%');
    bar.classList.toggle('empty', !score);
    bar.classList.toggle('today', dateKey(date) === dateKey(today));
    bar.querySelector('small').textContent = new Intl.DateTimeFormat(locale, { weekday: 'short' }).format(date);
  });

  const available = scores.filter(Boolean);
  let trend = '—';
  if (available.length >= 2) {
    const change = Math.round(((available[available.length - 1] - available[0]) / 3) * 100);
    trend = (change > 0 ? '+' : '') + change + '%';
  }
  document.querySelector('#weeklyTrend').textContent = trend;
}

function renderEnergyChart() {
  const points = [];
  for (let index = 0; index < 28; index += 1) {
    const date = new Date(today);
    date.setDate(today.getDate() - (27 - index));
    const log = state.logs.get(dateKey(date));
    if (!log) continue;
    const x = Math.round((index / 27) * 600);
    const y = { low: 145, medium: 90, high: 35 }[log.energy];
    points.push([x, y]);
  }

  const line = document.querySelector('#energyLine');
  const area = document.querySelector('#energyArea');
  const empty = document.querySelector('#energyChartEmpty');
  if (points.length < 2) {
    line.setAttribute('d', '');
    area.setAttribute('d', '');
    empty.hidden = false;
    return;
  }

  const path = points.map(function (point, index) {
    return (index ? 'L' : 'M') + point[0] + ' ' + point[1];
  }).join(' ');
  line.setAttribute('d', path);
  area.setAttribute('d', path + ' L' + points[points.length - 1][0] + ' 180 L' + points[0][0] + ' 180 Z');
  empty.hidden = true;
}

function setModal(modal, open, focusSelector) {
  modal.hidden = !open;
  document.body.classList.toggle('modal-open', open);
  if (open && focusSelector) {
    modal.querySelectorAll('.form-message').forEach(function (message) {
      message.textContent = '';
      message.classList.remove('success');
    });
    setTimeout(function () {
      document.querySelector(focusSelector).focus();
    }, 0);
  }
}

function handleAuthSuccess(result, message, modal, form) {
  localStorage.setItem('sana-user-name', result.user.name);
  applyProfileName(result.user.name);
  message.classList.add('success');
  form.reset();
  setTimeout(function () {
    setModal(modal, false);
  }, 900);
}

async function register(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const button = document.querySelector('#registerSubmit');
  const message = document.querySelector('#registerMessage');
  const payload = {
    name: form.elements.name.value.trim(),
    email: form.elements.email.value.trim(),
    password: form.elements.password.value
  };

  button.disabled = true;
  button.textContent = t('registering');
  message.textContent = '';
  try {
    const result = await apiRequest('/api/auth/register', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    message.textContent = t('registrationSuccess');
    handleAuthSuccess(result, message, registerModal, form);
  } catch (error) {
    message.textContent = error.status === 409 ? t('emailExists') : error.status ? t('registrationFailed') : t('backendRequired');
  } finally {
    button.disabled = false;
    button.textContent = t('register');
  }
}

async function login(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const button = document.querySelector('#loginSubmit');
  const message = document.querySelector('#loginMessage');
  const payload = {
    email: form.elements.email.value.trim(),
    password: form.elements.password.value
  };

  button.disabled = true;
  button.textContent = t('loggingIn');
  message.textContent = '';
  try {
    const result = await apiRequest('/api/auth/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    message.textContent = t('loginSuccess');
    handleAuthSuccess(result, message, loginModal, form);
  } catch (error) {
    message.textContent = error.status === 401 ? t('invalidLogin') : error.status ? t('loginFailed') : t('backendRequired');
  } finally {
    button.disabled = false;
    button.textContent = t('login');
  }
}

function updateNotificationsText() {
  const enabled = localStorage.getItem('sana-notifications') === 'true';
  document.querySelector('#notificationsValue').textContent = t(enabled ? 'notificationsOn' : 'notificationsOff');
  document.querySelector('#notificationsButton').setAttribute('aria-pressed', String(enabled));
}

function toggleNotifications() {
  const enabled = localStorage.getItem('sana-notifications') !== 'true';
  localStorage.setItem('sana-notifications', String(enabled));
  updateNotificationsText();
  showToast(t(enabled ? 'notificationsEnabled' : 'notificationsDisabled'));
}

function togglePrivacy() {
  const enabled = document.body.classList.toggle('privacy-mode');
  showToast(t(enabled ? 'privacyEnabled' : 'privacyDisabled'));
}

async function clearLocalData() {
  ['sana-logs', 'sana-periods', 'sana-notifications'].forEach(function (key) {
    localStorage.removeItem(key);
  });
  state.logs.clear();
  state.periods = [];
  await loadCalendarForecast();
  renderForecastSummary();
  renderCalendar();
  renderCharts();
  updateSelectedDate();
  showToast(t('cleared'));
}

function renderChat() {
  const container = document.querySelector('#chatMessages');
  if (!state.chatMessages.length) {
    state.chatMessages.push({ role: 'assistant', content: t('chatWelcome'), welcome: true });
  } else if (state.chatMessages.length === 1 && state.chatMessages[0].welcome) {
    state.chatMessages[0].content = t('chatWelcome');
  }

  container.innerHTML = '';
  state.chatMessages.forEach(function (message) {
    const bubble = document.createElement('div');
    bubble.className = 'chat-message ' + message.role;
    bubble.textContent = message.content;
    container.appendChild(bubble);
  });
  container.scrollTop = container.scrollHeight;
}

function setOllamaStatus(online) {
  const status = document.querySelector('#ollamaStatus');
  status.textContent = t(online ? 'ollamaOnline' : 'ollamaOffline');
  status.classList.toggle('online', online);
}

async function checkOllama() {
  try {
    const response = await fetch(ollamaBaseUrl + '/api/tags');
    if (!response.ok) throw new Error('Ollama error: ' + response.status);
    const data = await response.json();
    const models = Array.isArray(data.models) ? data.models.map(function (model) {
      return model.name || model.model;
    }).filter(Boolean) : [];
    const input = document.querySelector('#ollamaModel');
    if (models.length && !models.includes(input.value.trim())) {
      input.value = models[0];
      localStorage.setItem('sana-ollama-model', models[0]);
    }
    setOllamaStatus(true);
  } catch (error) {
    setOllamaStatus(false);
  }
}

async function sendChatMessage(event) {
  event.preventDefault();
  const input = document.querySelector('#chatInput');
  const button = document.querySelector('#chatSend');
  const question = input.value.trim();
  if (!question) return;

  state.chatMessages.push({ role: 'user', content: question });
  input.value = '';
  renderChat();
  button.disabled = true;
  button.textContent = t('sending');

  const model = document.querySelector('#ollamaModel').value.trim() || 'qwen2.5:3b';
  localStorage.setItem('sana-ollama-model', model);
  const messages = [
    {
      role: 'system',
      content: 'You are Sana, a direct and down-to-earth wellbeing assistant. Reply naturally in the same language as the user. Start with the answer immediately: do not greet the user, introduce yourself, repeat their name, or add filler phrases. Keep responses concise, practical, and conversational, with occasional dry humor only when it fits. Do not sound robotic, overly cheerful, or needlessly rude. Never insult, humiliate, threaten, or discriminate. Give only general educational wellbeing information, never diagnose, and clearly recommend professional medical care for dangerous or alarming symptoms.'
    }
  ].concat(state.chatMessages.filter(function (message) {
    return !message.welcome;
  }).map(function (message) {
    return { role: message.role, content: message.content };
  }));

  try {
    const response = await fetch(ollamaBaseUrl + '/api/chat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: model, messages: messages, stream: false })
    });
    if (!response.ok) throw new Error('Ollama error: ' + response.status);
    const data = await response.json();
    state.chatMessages.push({ role: 'assistant', content: data.message.content });
    setOllamaStatus(true);
  } catch (error) {
    state.chatMessages.push({ role: 'assistant', content: t('chatOffline') });
    setOllamaStatus(false);
  } finally {
    button.disabled = false;
    button.textContent = t('send');
    renderChat();
  }
}

function bindEvents() {
  document.querySelectorAll('[data-view]').forEach(function (button) {
    button.addEventListener('click', function () {
      setView(button.dataset.view);
    });
  });

  document.querySelectorAll('[data-go]').forEach(function (button) {
    button.addEventListener('click', function () {
      if (button.dataset.go === 'log') openLog();
      else setView(button.dataset.go);
    });
  });

  document.querySelectorAll('.lang').forEach(function (button) {
    button.addEventListener('click', function () {
      applyLanguage(button.dataset.lang);
    });
  });

  document.querySelector('#profileButton').addEventListener('click', function () {
    setView('profile');
  });
  document.querySelector('#profileLanguageButton').addEventListener('click', function () {
    applyLanguage(state.lang === 'kk' ? 'ru' : 'kk');
  });
  document.querySelector('#notificationsButton').addEventListener('click', toggleNotifications);
  document.querySelector('#privacyButton').addEventListener('click', togglePrivacy);
  document.querySelector('#clearData').addEventListener('click', clearLocalData);

  document.querySelectorAll('[data-open-register]').forEach(function (button) {
    button.addEventListener('click', function () {
      setModal(registerModal, true, '#registerName');
    });
  });
  document.querySelectorAll('[data-open-login]').forEach(function (button) {
    button.addEventListener('click', function () {
      setModal(loginModal, true, '#loginEmail');
    });
  });
  document.querySelector('#closeRegister').addEventListener('click', function () {
    setModal(registerModal, false);
  });
  document.querySelector('#closeLogin').addEventListener('click', function () {
    setModal(loginModal, false);
  });
  [registerModal, loginModal].forEach(function (modal) {
    modal.addEventListener('click', function (event) {
      if (event.target === modal) setModal(modal, false);
    });
  });
  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') {
      setModal(registerModal, false);
      setModal(loginModal, false);
    }
  });

  document.querySelector('#registerForm').addEventListener('submit', register);
  document.querySelector('#loginForm').addEventListener('submit', login);
  document.querySelector('#saveLog').addEventListener('click', saveLog);
  document.querySelector('#logPeriodButton').addEventListener('click', function () {
    markPeriod(dateKey(today));
  });
  document.querySelector('#markSelectedPeriodButton').addEventListener('click', function () {
    markPeriod(selectedDateKey());
  });

  document.querySelectorAll('.mood').forEach(function (button) {
    button.addEventListener('click', function () {
      state.mood = button.dataset.mood;
      syncLogChoices();
    });
  });
  document.querySelectorAll('#moodChoices button').forEach(function (button) {
    button.addEventListener('click', function () {
      state.mood = button.dataset.value;
      syncLogChoices();
    });
  });
  document.querySelectorAll('#energyChoices button').forEach(function (button) {
    button.addEventListener('click', function () {
      state.energy = button.dataset.value;
      syncLogChoices();
    });
  });
  document.querySelectorAll('#symptomChoices button').forEach(function (button) {
    button.addEventListener('click', function () {
      const value = button.dataset.value;
      if (value === 'none') {
        state.symptoms = ['none'];
      } else {
        state.symptoms = state.symptoms.filter(function (item) {
          return item !== 'none';
        });
        if (state.symptoms.includes(value)) {
          state.symptoms = state.symptoms.filter(function (item) {
            return item !== value;
          });
        } else {
          state.symptoms.push(value);
        }
        if (!state.symptoms.length) state.symptoms = ['none'];
      }
      syncLogChoices();
    });
  });

  document.querySelector('#prevMonth').addEventListener('click', async function () {
    state.shownMonth -= 1;
    if (state.shownMonth < 0) {
      state.shownMonth = 11;
      state.shownYear -= 1;
    }
    state.selectedDay = 1;
    await loadCalendarForecast();
    renderForecastSummary();
    updateSelectedDate();
    renderCalendar();
  });
  document.querySelector('#nextMonth').addEventListener('click', async function () {
    state.shownMonth += 1;
    if (state.shownMonth > 11) {
      state.shownMonth = 0;
      state.shownYear += 1;
    }
    state.selectedDay = 1;
    await loadCalendarForecast();
    renderForecastSummary();
    updateSelectedDate();
    renderCalendar();
  });

  document.querySelector('#insertTemplate').addEventListener('click', function () {
    const notes = document.querySelector('#notes');
    notes.value = t('templateText');
    notes.focus();
  });
  document.querySelector('#chatForm').addEventListener('submit', sendChatMessage);
}

async function init() {
  bindEvents();
  const savedModel = localStorage.getItem('sana-ollama-model');
  if (savedModel) document.querySelector('#ollamaModel').value = savedModel;
  applyProfileName(localStorage.getItem('sana-user-name'));
  fillLogForm(dateKey(today));
  applyLanguage(state.lang);
  await loadTrackerData();
  checkOllama();
}

init();
